ArkManifest.define({id:"worldminute",title:"In one minute (3D)",route:"/how-it-works",group:"page",meta:{},fields:{HERE:{label:"Shared: crumb",kind:"line",section:"Shared",value:"In one minute"},NOTE:{label:"Note under the stage",kind:"line",section:"Shared",value:"A sample network. Nothing here is live."},"BEAT1.NAME":{label:"Beat 1: short name (the tick and the label)",kind:"line",section:"Beat 1",value:"Your key"},"BEAT1.SAY":{label:"Beat 1: the sentence",kind:"text",section:"Beat 1",value:"You hold one key. It signs every record on your own chain."},"BEAT1.TAG.NAME":{label:"Beat 1: 3D label",kind:"line",section:"Beat 1",value:"Your chain"},"BEAT1.TAG.SUB":{label:"Beat 1: 3D label, second line",kind:"line",section:"Beat 1",value:"Sample"},"BEAT2.NAME":{label:"Beat 2: short name (the tick and the label)",kind:"line",section:"Beat 2",value:"Your chain"},"BEAT2.SAY":{label:"Beat 2: the sentence",kind:"text",section:"Beat 2",value:"Each record names the one before it. A mistake is fixed by a new record."},"BEAT2.TAG.NAME":{label:"Beat 2: 3D label",kind:"line",section:"Beat 2",value:"Your chain"},"BEAT2.TAG.SUB":{label:"Beat 2: 3D label, second line",kind:"line",section:"Beat 2",value:"Oldest to newest"},"BEAT3.NAME":{label:"Beat 3: short name (the tick and the label)",kind:"line",section:"Beat 3",value:"The kernel"},"BEAT3.SAY":{label:"Beat 3: the sentence",kind:"text",section:"Beat 3",value:"DEFXN is the kernel. FXN is the first chain, and other network chains can run beside it."},"BEAT3.TAG.NAME":{label:"Beat 3: 3D label",kind:"line",section:"Beat 3",value:"FXN"},"BEAT3.TAG.SUB":{label:"Beat 3: 3D label, second line",kind:"line",section:"Beat 3",value:"First chain"},"BEAT4.NAME":{label:"Beat 4: short name (the tick and the label)",kind:"line",section:"Beat 4",value:"A resolver"},"BEAT4.SAY":{label:"Beat 4: the sentence",kind:"text",section:"Beat 4",value:"A resolver reads signed records, applies its rules, and signs the result."},"BEAT4.TAG.NAME":{label:"Beat 4: 3D label",kind:"line",section:"Beat 4",value:"Resolver"},"BEAT4.TAG.SUB":{label:"Beat 4: 3D label, second line",kind:"line",section:"Beat 4",value:"Rule set"},"BEAT5.NAME":{label:"Beat 5: short name (the tick and the label)",kind:"line",section:"Beat 5",value:"Keepers"},"BEAT5.SAY":{label:"Beat 5: the sentence",kind:"text",section:"Beat 5",value:"A keeper orders each record and returns a signed receipt. The receipt makes it final. Pinners on our own nodes hold copies."},"BEAT5.TAG.NAME":{label:"Beat 5: 3D label",kind:"line",section:"Beat 5",value:"Keeper"},"BEAT5.TAG.SUB":{label:"Beat 5: 3D label, second line",kind:"line",section:"Beat 5",value:"Built, not live"},"BEAT6.NAME":{label:"Beat 6: short name (the tick and the label)",kind:"line",section:"Beat 6",value:"A name"},"BEAT6.SAY":{label:"Beat 6: the sentence",kind:"text",section:"Beat 6",value:"A name is flat, like radio.fxn. One signed record says who owns it."},"BEAT6.TAG.NAME":{label:"Beat 6: 3D label",kind:"line",section:"Beat 6",value:"radio.fxn"},"BEAT6.TAG.SUB":{label:"Beat 6: 3D label, second line",kind:"line",section:"Beat 6",value:"Sample name"},"BEAT7.NAME":{label:"Beat 7: short name (the tick and the label)",kind:"line",section:"Beat 7",value:"Your card"},"BEAT7.SAY":{label:"Beat 7: the sentence",kind:"text",section:"Beat 7",value:"Your card is built from pieces. Your record picks them."},"BEAT7.TAG.NAME":{label:"Beat 7: 3D label",kind:"line",section:"Beat 7",value:"Card"},"BEAT7.TAG.SUB":{label:"Beat 7: 3D label, second line",kind:"line",section:"Beat 7",value:"Sample"},"BEAT8.NAME":{label:"Beat 8: short name (the tick and the label)",kind:"line",section:"Beat 8",value:"Your look"},"BEAT8.SAY":{label:"Beat 8: the sentence",kind:"text",section:"Beat 8",value:"A site you visit can show your card. The site keeps its own layout."},"BEAT8.TAG.NAME":{label:"Beat 8: 3D label",kind:"line",section:"Beat 8",value:"Skin"},"BEAT8.TAG.SUB":{label:"Beat 8: 3D label, second line",kind:"line",section:"Beat 8",value:"Sample"},"BEAT9.NAME":{label:"Beat 9: short name (the tick and the label)",kind:"line",section:"Beat 9",value:"Proof"},"BEAT9.SAY":{label:"Beat 9: the sentence",kind:"text",section:"Beat 9",value:"Anyone can check. Follow the signatures back to the start."},"BEAT9.TAG.NAME":{label:"Beat 9: 3D label",kind:"line",section:"Beat 9",value:"Genesis"},"BEAT9.TAG.SUB":{label:"Beat 9: 3D label, second line",kind:"line",section:"Beat 9",value:"Signed"},"BEATS.LABEL":{label:"Beat list: accessible name",kind:"line",section:"Controls",value:"The nine beats"},"TICK.LABEL":{label:"Beat button: accessible name",kind:"line",section:"Controls",value:"Go to beat {n}: {name}"},PLAY:{label:"Play",kind:"line",section:"Controls",value:"Play"},PAUSE:{label:"Pause",kind:"line",section:"Controls",value:"Pause"},BACK:{label:"Back",kind:"line",section:"Controls",value:"Back"},SKIP:{label:"Skip to the end",kind:"line",section:"Controls",value:"Skip"},RESTART:{label:"Start again",kind:"line",section:"Controls",value:"Start again"},"END.CTA":{label:"End: the one action",kind:"line",section:"End",value:"Initiate FXN ID"},"END.CTA.HREF":{label:"End: button link target",kind:"link",section:"End",value:"route:identity"},"CARD.LABEL":{label:"Card layer: accessible name",kind:"line",section:"Card",value:"A sample identity card forming from its pieces"},"CARD.SAMPLE":{label:"Card: sample label",kind:"line",section:"Card",value:"Sample card"},"CARD.PIECES":{label:"Card: the pieces, in words",kind:"text",section:"Card",value:"Pieces: frame, corner, tag, ornament, divider, emblem. Layers: backdrop, aura, mark, signal, particles."},"CARD.FAILED":{label:"Card: art did not load",kind:"text",section:"Card",value:"The card art did not load. The pieces are listed below."},"SITE.LABEL":{label:"Site pane: accessible name",kind:"line",section:"Card",value:"A sample site wearing the card"},"SITE.NAME":{label:"Site pane: name",kind:"line",section:"Card",value:"radio.fxn"},"SITE.TEXT":{label:"Site pane: text",kind:"text",section:"Card",value:"A sample page in the card\u2019s look."},"SITE.BUTTON":{label:"Site pane: button",kind:"line",section:"Card",value:"Open"},KICKER:{label:"Kicker above the answer",kind:"line",section:"One page",value:"How it works"},"SHOW.GO":{label:"The dominant action: plays the show in the 3D space",kind:"line",section:"One page",value:"Play the show"},ANSWER:{label:"The answer, first line of the page",kind:"line",section:"One page",value:"You ask. A signed rulebook answers, and anyone can check it."},"PARTS.LABEL":{label:"Label of the three closer looks",kind:"line",section:"One page",value:"Look closer"},"PART.RESOLVE.NAME":{label:"Tab: a result",kind:"line",section:"One page",value:"How a result is made"},"PART.RESOLVE.LINE":{label:"Tab: a result, one line",kind:"line",section:"One page",value:"Two people sign. A resolver checks both and signs the result."},"PART.LAYERS.NAME":{label:"Tab: layers",kind:"line",section:"One page",value:"Three layers"},"PART.LAYERS.LINE":{label:"Tab: layers, one line",kind:"line",section:"One page",value:"Each layer has one rule."},"PART.LAYERS.L1":{label:"Layer 1, short",kind:"line",section:"One page",value:"Kernel: the shared base. It never learns what a record means."},"PART.LAYERS.L2":{label:"Layer 2, short",kind:"line",section:"One page",value:"Capabilities: tested building blocks. Each ships with its checks."},"PART.LAYERS.L3":{label:"Layer 3, short",kind:"line",section:"One page",value:"Resolvers: signed rule sets. Each names its blocks."},"PART.LIFE.NAME":{label:"Tab: life",kind:"line",section:"One page",value:"A resolver\u2019s life"},"PART.LIFE.LINE":{label:"Tab: life, one line",kind:"line",section:"One page",value:"A builder takes a resolver from build to inspect."}}});
;
