ArkManifest.define({id:"chain",title:"Every identity, its own chain",route:"/chain",group:"page",meta:{back:"zero",diagrams:[{id:"swap-signed-resolution",place:"chain: the Swaps case, in place of the payload-read illustration",caption:"Illustration \xB7 relationships, not live state",flow:["Two intents enter","One signer resolves the batch","One signed result goes to peers"],refusal:{from:"A second node",tag:"resolved by <signer>"}}]},fields:{EYEBROW:{label:"Eyebrow",kind:"line",section:"Page",value:"DEFXN / ONE CHAIN PER SIGNER"},TITLE:{label:"Heading",kind:"line",section:"Page",value:"Each key keeps its own chain."},LEDE:{label:"Introduction",kind:"text",section:"Page",value:"What it is: every FXN ID signs records onto its own list, and every resolver runs its own chain. One base chain lists which resolvers and capabilities exist. What you do: sign a record. What you get back: a keeper's signed receipt, which makes it final. No record waits on another key's list. Status: built, not live. The new devnet is not deployed."},NEXT:{label:"Next-step link",kind:"line",section:"Page",value:"See what each resolver reads from the chain"},"NEXT.HREF":{label:"Next-step link target",kind:"link",section:"Page",value:"route:resolvers"},"SOURCE.LINK":{label:"Where resolver chains come from (link)",kind:"line",section:"Page",value:"Where do resolver chains come from?"},"SOURCE.HREF":{label:"Where resolver chains come from (link target)",kind:"link",section:"Page",value:"route:resolver"}}});
;
/* ---- js/content/manifests/resolver.js ---- */
ArkManifest.define({id:"resolver",title:"What is a resolver?",route:"/what-is-a-resolver",group:"page",meta:{next:"resolutions",back:"zero",diagrams:[{id:"resolver-layers",place:"what-is-a-resolver: Understand-why depth (BODY2), and /resolvers above the resolver chains",caption:"Illustration \xB7 relationships, not live state",bands:[{id:"base",label:"Base chain",rule:"never learns a business kind",marks:["launch a resolver","upgrade it","launch a capability","records"]},{id:"capabilities",label:"Capabilities",rule:"published with its tests",from:"ArkRegistrySnapshot.capabilities",badge:"vectors",stub:"sourceHash"},{id:"resolvers",label:"Resolver chains",rule:"composes, never copies",from:"ArkRegistrySnapshot.resolvers",show:["dao","treasury"],plus:"your-resolver",lines:"composes"}],phone:"bands stack; composition lines become capability chips under each resolver"},{id:"launched-vs-served",place:"what-is-a-resolver: beside BODY3 (Essential boundary)",caption:"Illustration \xB7 relationships, not live state",frames:[{state:"launched",outline:"dashed",note:"launched, no provider: answers nothing"},{state:"served",outline:"solid",provider:!0,badge:"proof",note:"a provider announces, with a proof for each composed capability"}]}]},fields:{TITLE:{label:"Heading",kind:"line",section:"Page",value:"A rulebook with its own chain."},"DISPLAY.TITLE":{label:"Display heading",kind:"line",section:"Page",value:"Send a record. Get a signed result you can check."},"DISPLAY.LEDE":{label:"Display introduction",kind:"text",section:"Page",value:"What it is: a rule set that runs as its own chain, launched by one signed record. What you do: send a record in its grammar. What you get back: its signed result, or a refusal with the reason. Status: built. Explore and Deploy run on the development network. Public hosting is not open."},BODY1:{label:"First paragraph",kind:"text",section:"Page",value:"A resolver is a rulebook that runs as its own chain. One signed launch record gives it a chain id, names the capabilities it is built from, and publishes the grammar every one of its records must follow."},BODY2:{label:"Second paragraph",kind:"text",section:"Page",value:"Capabilities are the shared mechanisms: N-of-M signatures, custody, a ledger, escrow, a signer. Each is published once, with test vectors anyone can run. A resolver names the ones it uses and adds its own grammar. It never carries its own copy. So two resolvers that both hold funds hold them the same, checked way."},BODY3:{label:"Closing paragraph",kind:"text",section:"Page",value:"Launched is not served. A resolver answers only while a provider announces for it. If it is built from capabilities, only a provider that passed their test vectors gets a seat."},"FLOW.LABEL":{label:"Flow label",kind:"line",section:"Flow",value:"One rulebook, one chain"},INPUT:{label:"Input title",kind:"line",section:"Flow",value:"Ask"},"INPUT.TEXT":{label:"Input description",kind:"line",section:"Flow",value:"Send a record in its grammar."},LOGIC:{label:"Logic title",kind:"line",section:"Flow",value:"Resolve"},"LOGIC.TEXT":{label:"Logic description",kind:"line",section:"Flow",value:"Apply its capabilities."},CLAIM:{label:"Claim title",kind:"line",section:"Flow",value:"Check"},"CLAIM.TEXT":{label:"Claim description",kind:"line",section:"Flow",value:"Receive its signed result."},"WHY.LABEL":{label:"Why label",kind:"line",section:"Page",value:"Before you rely on it"},WHY:{label:"Why text",kind:"text",section:"Page",value:"You can read the rule set before you send: its grammar, its capabilities and the key that can change it. A change adds a new version that anyone can see."},"BOUNDARY.LABEL":{label:"Boundary label",kind:"line",section:"Page",value:"Trust boundary"},BOUNDARY:{label:"Boundary text",kind:"text",section:"Page",value:"Its signature is its result. Whether to rely on that resolver is decided before you send anything: its grammar, its capabilities, who can change it."},SOURCE:{label:"Source link",kind:"line",section:"Links",value:"Read the resolver spec"},"SOURCE.HREF":{label:"Source link target",kind:"link",section:"Links",value:"doc:docs/protocol/resolvers.md"},"HOME.HREF":{label:"Breadcrumb: Home link",kind:"link",section:"Links",value:"route:zero"},"INSPECT.HREF":{label:"Inspect reference evidence link",kind:"link",section:"Links",value:"route:references"},"STATUS.HREF":{label:"Status page link",kind:"link",section:"Links",value:"doc:docs/status.md"},NEXT:{label:"Onward link",kind:"line",section:"Links",value:"Deploy a resolver"},BACK:{label:"Back link",kind:"line",section:"Links",value:"\u2190 Home"},"ASK.BODY":{label:"Ask step text",kind:"text",section:"Flow",value:"A resolver accepts only records in its own grammar. Anything else is refused before it reaches a peer. This example takes a document identifier and checks it against a named size rule."},"RESOLVE.BODY":{label:"Resolve step text",kind:"text",section:"Flow",value:"A provider of that resolver applies its capabilities to the record. The same capability, at the same version, gives the same answer on every provider: run it again on the same input and the result does not change."},"CHECK.BODY":{label:"Check step text",kind:"text",section:"Flow",value:"The provider signs the result, and its signature is its result. So the trust question comes first: before you send anything, read its grammar, its capabilities and who can change it. Explore re-checks every hash and signature in your browser."},LAWS:{label:"Laws step title",kind:"line",section:"Laws",value:"Laws"},"LAWS.BODY":{label:"Laws step text",kind:"text",section:"Laws",value:"Four rules every resolver follows on the network."},LAW1:{label:"Law 1",kind:"line",section:"Laws",value:"One launch, one chain."},"LAW1.TEXT":{label:"Law 1 detail",kind:"text",section:"Laws",value:"A single signed record gives a resolver its chain id, its providers and its manifests. Its whole history is readable, oldest first."},LAW2:{label:"Law 2",kind:"line",section:"Laws",value:"Built from checked parts."},"LAW2.TEXT":{label:"Law 2 detail",kind:"text",section:"Laws",value:"A resolver names the capabilities it composes. The network refuses a launch that names a capability that is not launched, or not the current version."},LAW3:{label:"Law 3",kind:"line",section:"Laws",value:"Its grammar is the gate."},"LAW3.TEXT":{label:"Law 3 detail",kind:"text",section:"Laws",value:"Every record is checked against the grammar the resolver published at launch, before it reaches any peer. A record that does not fit is refused, with the reason."},LAW4:{label:"Law 4",kind:"line",section:"Laws",value:"Fixed unless it has a control key."},"LAW4.TEXT":{label:"Law 4 detail",kind:"text",section:"Laws",value:"A resolver is immutable by default. Only the control key named at launch can upgrade it. An upgrade adds a new declaration and never rewrites the old one."},"VERIFIED.TITLE":{label:"Verified-on-chain heading",kind:"line",section:"Hub",value:"What \u201Cverified on chain\u201D means"},"VERIFIED.FACT1":{label:"Verified fact 1: vectors",kind:"text",section:"Hub",value:"Its tests are its own. A capability\u2019s test vectors come from its crate\u2019s own test suite, with a hash of the exact source they ran against."},"VERIFIED.FACT2":{label:"Verified fact 2: provider proof",kind:"text",section:"Hub",value:"Providers prove them. A provider that serves a resolver built on a capability must pass that capability\u2019s vectors first, and the provider list records the proof."},"VERIFIED.FACT3":{label:"Verified fact 3: composition check",kind:"text",section:"Hub",value:"Launches are checked. A launch that names a capability that is not launched, or not the current version, is refused."},"VERIFIED.PLANNED":{label:"Verified: planned line",kind:"text",section:"Hub",value:"Planned, not built: audits by providers and reviewers, bounties for findings, and an option to require audited capabilities."},"REGISTRY.LINK":{label:"Hub link: resolvers and capabilities",kind:"line",section:"Hub",value:"Every resolver and capability"},"REGISTRY.HREF":{label:"Hub link target: resolvers and capabilities",kind:"link",section:"Hub",value:"route:resolvers"},"DEPLOY.LINK":{label:"Hub link: deploy a resolver",kind:"line",section:"Hub",value:"Deploy a resolver"},"DEPLOY.HREF":{label:"Hub link target: deploy a resolver",kind:"link",section:"Hub",value:"route:resolutions/deployments"},"EXPLORE.LINK":{label:"Hub link: Explore product",kind:"line",section:"Hub",value:"Open Explore"},"EXPLORE.HREF":{label:"Hub link target: Explore product",kind:"link",section:"Hub",value:"url:https://explore.defxn.com"},"DEPLOYER.LINK":{label:"Hub link: Deploy product",kind:"line",section:"Hub",value:"Open Deploy"},"DEPLOYER.HREF":{label:"Hub link target: Deploy product",kind:"link",section:"Hub",value:"url:https://deploy.defxn.com"},"PRODUCTS.NOTE":{label:"Hub note: product hosting",kind:"text",section:"Hub",value:"Explore and Deploy run on the development network. Public hosting is not open yet."},"MATH.LINK":{label:"Hub link: resolver math",kind:"line",section:"Hub",value:"How a resolver's limits are set"},"MATH.HREF":{label:"Hub link target: resolver math",kind:"link",section:"Hub",value:"route:resolver-math"},"REGISTRY.KICKER":{label:"Registry page: kicker",kind:"line",section:"Registry page",value:"A resolver runs its own chain \xB7 built from shared capabilities"},"REGISTRY.TITLE":{label:"Registry page: heading",kind:"line",section:"Registry page",value:"Resolvers and capabilities"},"REGISTRY.LEDE":{label:"Registry page: introduction",kind:"text",section:"Registry page",value:"This page is a dated snapshot of every first-party resolver chain and every capability, read from the code that defines them. Each row opens in Explore, which reads a node directly."},"REGISTRY.BOUNDARY":{label:"Registry page: boundary",kind:"text",section:"Registry page",value:"A snapshot, not a live read. Every count here comes from the commit and the dated development-network reading named above. What a node holds right now is in Explore."},"REGISTRY.CHAINS.LABEL":{label:"Registry page: resolver chains label",kind:"line",section:"Registry page",value:"Resolver chains"},"REGISTRY.CHAINS.BODY":{label:"Registry page: resolver chains text",kind:"text",section:"Registry page",value:"Each resolver below is its own chain, launched by one signed record. \u201CGrammar enforced\u201D means every record is checked against the grammar the resolver published. \u201CUnspecified\u201D means a legacy grammar the network admits and reports, without checking."},"REGISTRY.CAPS.LABEL":{label:"Registry page: capabilities label",kind:"line",section:"Registry page",value:"Capabilities"},"REGISTRY.CAPS.BODY":{label:"Registry page: capabilities text",kind:"text",section:"Registry page",value:"A capability is one shared mechanism, published with the tests that define it. A provider must pass those tests before it may serve any resolver that uses it."},"REGISTRY.CAPS.EMPTY":{label:"Registry page: no capability launched",kind:"text",section:"Registry page",value:"Launched on the development network at its last recorded restart: none. That is a measured zero, not a missing feature. The manifests below are ready to launch."},"REGISTRY.BRIDGES.LABEL":{label:"Registry page: bridge chains label",kind:"line",section:"Registry page",value:"Bridge chains"},"REGISTRY.BRIDGES.BODY":{label:"Registry page: bridge chains text",kind:"text",section:"Registry page",value:"These products also write their records to resolver chains of their own, beside the older paths they still use."},"REGISTRY.DEPLOY.TITLE":{label:"Registry page: deploy heading",kind:"line",section:"Registry page",value:"Deploy your own"},"REGISTRY.DEPLOY.STEPS":{label:"Registry page: deploy steps (one per line)",kind:"text",section:"Registry page",value:`Write your grammar. Derive it from your own sample records.
Name the capabilities you build on.
Choose: immutable, or upgradeable by one key.
Review the exact record and sign it at deploy.defxn.com.
Run a provider for it. If you compose capabilities, prove them first.`},"REGISTRY.DEPLOY.LINK":{label:"Registry page: deploy walkthrough link",kind:"line",section:"Registry page",value:"Full walkthrough"},"REGISTRY.OPEN":{label:"Registry page: per-row Explore link",kind:"line",section:"Registry page",value:"Open in Explore"},"REGISTRY.APPS.LABEL":{label:"Registry page: applications heading",kind:"line",section:"Registry page",value:"Applications that read records but are not resolver chains yet"},"REGISTRY.APPS.BODY":{label:"Registry page: applications text",kind:"text",section:"Registry page",value:"Listed on this page before resolver chains existed. None of them is launched as a resolver chain. Each keeps its own figures and open issues, dated where they were measured."}}});
;
/* ---- js/content/manifests/resolvermath.js ---- */
ArkManifest.define({id:"resolvermath",title:"Resolver Math",route:"/resolver-math",group:"page",meta:{back:"resolver"},fields:{EYEBROW:{label:"Page eyebrow",kind:"line",section:"Header",value:"DEFXN \xB7 Foundational concept"},TITLE:{label:"Page title",kind:"line",section:"Header",value:"Resolver Math"},DECK:{label:"Opening summary under the title",kind:"text",section:"Header",value:"A record is a tuple of symbols. Meaning is symbol \xD7 position \xD7 observer \u2014 and the observer is the resolver."},CLAIM:{label:"The consequence, in the panel beside the observer section",kind:"text",section:"The observer",value:"An unbounded space of meanings needs a pinned observer to be worth anything."},CLAIM2:{label:"The line that states the page's thesis",kind:"line",section:"The observer",value:"Your resolver\u2019s limits are your limitations."},BOUNDARY:{label:"Note above the dimension table",kind:"text",section:"The boundary",value:"\u201CInfinite dimensions, zero cost\u201D is half right, and the half that is wrong is the expensive half. Each layer below was decided by a hazard somebody hit."},FOOTER:{label:"The one path, repeated at the foot of the page",kind:"line",section:"Keep reading",value:"Two parties sign \u2192 a resolver shard resolves \u2192 the shard signs the result \u2192 replicas store \u2192 anyone audits."}}});
;
/* ---- js/content/manifests/references.js ---- */
ArkManifest.define({id:"references",title:"Reference resolvers",route:"/start-from-something-real",group:"page",meta:{next:"resolutions",back:"resolver"},fields:{TITLE:{label:"Heading",kind:"line",section:"Page",value:"Reference resolvers are not published yet."},BODY1:{label:"First paragraph",kind:"text",section:"Page",value:"A reference resolver is a worked example to start from when you build your own. CR3TV and DeArk are named as the first two, but neither has a public record you can inspect yet. Until one does, start from the resolver chains in Resolvers and capabilities: each one opens in Explore."},BODY2:{label:"Second paragraph",kind:"text",section:"Page",value:"A name becomes a reference when its record is registered in the evidence registry. Until then, nothing here shows that CR3TV or DeArk is deployed or in production."},BODY3:{label:"Closing paragraph",kind:"text",section:"Page",value:"A publishable reference must include its purpose, current status and observation date, resolver or network identifier, source or manifest location, and the exact boundary of what it proves."},NEXT:{label:"Onward link",kind:"line",section:"Links",value:"Deploy a resolver"},BACK:{label:"Back link",kind:"line",section:"Links",value:"What is a resolver"},"START.LINK":{label:"Main action: where to start today",kind:"line",section:"Links",value:"Every resolver and capability"},"START.HREF":{label:"Main action target",kind:"link",section:"Links",value:"route:resolvers"},"SOURCE.HREF":{label:"Source link target",kind:"link",section:"Links",value:"doc:docs/evidence/registry.md"},"HOME.HREF":{label:"Breadcrumb: Home link",kind:"link",section:"Links",value:"route:zero"}}});
;
/* ---- js/content/manifests/deployment.js ---- */
ArkManifest.define({id:"deployment",title:"Deploy a resolver",route:"/how-deployment-works",group:"page",meta:{next:"download",back:"resolver",primary:!0,diagrams:[{id:"deploy-flow",place:"how-deployment-works: above the three cards (desktop), replacing the card meshes on phones",caption:"Illustration \xB7 relationships, not live state",stations:["grammar","capabilities","control","review and sign","serve","explorer"],fork:{at:"control",branches:["immutable","one control key"]},badges:{serve:"proof"},refusals:[{at:"grammar",when:"before signing",name:"grammar does not compile"},{at:"capabilities",when:"at the node",name:"CapabilityNotLaunched"}],note:"refusals are drawn as short side exits carrying their exact refusal names: a refusal names the problem, it never fails silently"}]},fields:{EYEBROW:{label:"Eyebrow",kind:"line",section:"Page",value:"DEFXN / DEPLOY A RESOLVER"},TITLE:{label:"Heading",kind:"line",section:"Page",value:"Deploy a resolver"},BODY1:{label:"First paragraph",kind:"text",section:"Page",value:"Say exactly what your records look like: their kinds, their fields, and which fields every record carries. Derive it from real sample records, not by hand. The deployer compiles it with the network\u2019s own compiler before you sign."},BODY2:{label:"Second paragraph",kind:"text",section:"Page",value:"List the shared mechanisms your resolver uses: signatures, custody, a ledger, escrow. The network refuses a launch that names one it has not launched."},BODY3:{label:"Third paragraph",kind:"text",section:"Page",value:"Immutable: nobody, ever, including you. Or one control key: only that key can sign an upgrade, and every upgrade is a new record that sits beside the old one."},BODY4:{label:"Fourth paragraph",kind:"text",section:"Page",value:"The deployer shows the exact unsigned record. You sign only after you have read it. The network answers with the record\u2019s ID, or a refusal that says what is missing."},BODY5:{label:"Fifth paragraph",kind:"text",section:"Page",value:"A provider announces an address for your chain. If your resolver uses capabilities, the provider first proves it runs them by passing their test vectors."},BODY6:{label:"Step 6 text",kind:"text",section:"Steps",value:"Every record your resolver admits appears in the explorer, oldest first, re-checked in your browser. The signature on a record is the result. Whether to rely on that resolver is decided before anyone sends it anything: its grammar, its capabilities, who can change it. Steps 1 to 3 set all three."},STEP1:{label:"Step 1 title",kind:"line",section:"Steps",value:"Write the grammar"},STEP2:{label:"Step 2 title",kind:"line",section:"Steps",value:"Name your capabilities"},STEP3:{label:"Step 3 title",kind:"line",section:"Steps",value:"Choose who can change it"},STEP4:{label:"Step 4 title",kind:"line",section:"Steps",value:"Review and sign"},STEP5:{label:"Step 5 title",kind:"line",section:"Steps",value:"Serve it"},STEP6:{label:"Step 6 title",kind:"line",section:"Steps",value:"Watch it"},NEXT:{label:"Main button",kind:"line",section:"Links",value:"Run DEFXN from source"},BACK:{label:"Back link",kind:"line",section:"Links",value:"What is a resolver?"},SUMMARY:{label:"Primary answer",kind:"text",section:"Story",value:"What it is: one signed launch record that gives your resolver its own chain, names its capabilities and publishes its grammar. What you do: write the grammar, name the capabilities, choose who can change it, read the record and sign it. What you get back: the record's ID and a chain for your resolver. A provider then serves it. Status: built, on the development network only."},BOUNDARY:{label:"Essential boundary",kind:"text",section:"Story",value:"Launched is not served. A resolver with no announcing provider answers nothing. The explorer and deployer run on the development network today. Public hosting is not open."},"FABRIC.NETWORK":{label:"Network fabric explanation",kind:"line",section:"Story",value:"A name for miner presence. It is not a resolver chain."},"FABRIC.LOGIC":{label:"Logic fabric explanation",kind:"line",section:"Story",value:"A resolver, launched on a chain of its own."},"FABRIC.INTENT":{label:"Intent fabric explanation",kind:"line",section:"Story",value:"A request waits for an offer and accepted terms (earlier agreement path)."},"FABRIC.FULFILLMENT":{label:"Fulfillment fabric explanation",kind:"line",section:"Story",value:"Signed evidence lands on the provider\u2019s chain, citing the agreement (earlier agreement path)."},"FABRIC.RECEIPT":{label:"Receipt fabric explanation",kind:"line",section:"Story",value:"An outcome is recorded under identified rules (earlier agreement path)."},"SIMPLE.TITLE":{label:"Title",kind:"line",section:"Simple story",value:"Deploy a resolver"},"SIMPLE.INTRO":{label:"Intro",kind:"text",section:"Simple story",value:"You deploy a resolver in three stages: write its grammar, sign one launch record, and have a provider serve it."},"SIMPLE.WRITE.TITLE":{label:"Card 1 title",kind:"line",section:"Deploy cards",value:"Write it"},"SIMPLE.WRITE.SIGNAL":{label:"Card 1 signal",kind:"line",section:"Deploy cards",value:"GRAMMAR \xB7 CAPABILITIES"},"SIMPLE.WRITE.TEXT":{label:"Card 1 text",kind:"text",section:"Deploy cards",value:"Your records\u2019 grammar, and the shared capabilities you build on."},"SIMPLE.LAUNCH.TITLE":{label:"Card 2 title",kind:"line",section:"Deploy cards",value:"Launch it"},"SIMPLE.LAUNCH.SIGNAL":{label:"Card 2 signal",kind:"line",section:"Deploy cards",value:"CONTROL \xB7 SIGN"},"SIMPLE.LAUNCH.TEXT":{label:"Card 2 text",kind:"text",section:"Deploy cards",value:"Choose who can change it, then read and sign one record."},"SIMPLE.SERVE.TITLE":{label:"Card 3 title",kind:"line",section:"Deploy cards",value:"Serve it"},"SIMPLE.SERVE.SIGNAL":{label:"Card 3 signal",kind:"line",section:"Deploy cards",value:"PROVIDER \xB7 EXPLORER"},"SIMPLE.SERVE.TEXT":{label:"Card 3 text",kind:"text",section:"Deploy cards",value:"A provider proves and announces it. Every record it admits shows in the explorer."},"SIMPLE.CAUTION.TITLE":{label:"Caution disclosure title",kind:"line",section:"Deploy cards",value:"Before you sign"},"SIMPLE.CAUTION":{label:"Caution disclosure text",kind:"text",section:"Deploy cards",value:"A launch uses a position on your own key\u2019s chain. Signing two different records at the same position freezes that key for good. Launch once per key, or use a fresh key."},"SIMPLE.PLANNED.TITLE":{label:"Planned disclosure title",kind:"line",section:"Deploy cards",value:"What\u2019s next \xB7 Planned"},"SIMPLE.PLANNED":{label:"Planned disclosure text",kind:"text",section:"Deploy cards",value:"One deployer for sites, apps, databases, packages, modules and code. Each lands as records on its own resolver chain. Also planned: audits and bounties for capabilities, and service pools. None of these is built yet."},"SIMPLE.DEPLOYER.LINK":{label:"Action: Deploy product",kind:"line",section:"Deploy cards",value:"Open Deploy"},"SIMPLE.DEPLOYER.HREF":{label:"Action target: Deploy product",kind:"link",section:"Deploy cards",value:"url:https://deploy.defxn.com"},"SIMPLE.EXPLORE.LINK":{label:"Action: Explore product",kind:"line",section:"Deploy cards",value:"See launched resolvers in Explore"},"SIMPLE.EXPLORE.HREF":{label:"Action target: Explore product",kind:"link",section:"Deploy cards",value:"url:https://explore.defxn.com"},"SIMPLE.REGISTRY.LINK":{label:"Action: resolvers and capabilities",kind:"line",section:"Deploy cards",value:"Every resolver and capability"},"SIMPLE.REGISTRY.HREF":{label:"Action target: resolvers and capabilities",kind:"link",section:"Deploy cards",value:"route:resolvers"},"SIMPLE.AGREEMENT.TITLE":{label:"Agreement chapters heading",kind:"line",section:"Deploy cards",value:"Hire a provider: the earlier path"},"SIMPLE.AGREEMENT.TEXT":{label:"Agreement chapters text",kind:"text",section:"Deploy cards",value:"Request, terms, result: how a client hired a provider under the earlier agreement path. It is no longer the direction and is kept read-only for reference."},"SIMPLE.ASK.TITLE":{label:"Ask Title",kind:"line",section:"Simple story",value:"State the request"},"SIMPLE.ASK.TEXT":{label:"Ask Text",kind:"text",section:"Simple story",value:"Name the work, the result you expect, and the limits that matter."},"SIMPLE.ASK.ACTION":{label:"Ask action",kind:"line",section:"Simple story",value:"Explore the request"},"SIMPLE.ASK.HREF":{label:"Ask card target",kind:"link",section:"Simple story",value:"route:how/ask"},"SIMPLE.WORK.TITLE":{label:"Work Title",kind:"line",section:"Simple story",value:"Agree on the terms"},"SIMPLE.WORK.TEXT":{label:"Work Text",kind:"text",section:"Simple story",value:"A provider proposes terms. Work begins after both sides accept the same promise."},"SIMPLE.WORK.ACTION":{label:"Work action",kind:"line",section:"Simple story",value:"Explore the agreement"},"SIMPLE.WORK.HREF":{label:"Work card target",kind:"link",section:"Simple story",value:"route:how/work"},"SIMPLE.CHECK.TITLE":{label:"Check Title",kind:"line",section:"Simple story",value:"Verify the result"},"SIMPLE.CHECK.TEXT":{label:"Check Text",kind:"text",section:"Simple story",value:"Return the work with evidence, check it against the agreement, and record the outcome."},"SIMPLE.CHECK.ACTION":{label:"Check action",kind:"line",section:"Simple story",value:"Explore verification"},"SIMPLE.CHECK.HREF":{label:"Check card target",kind:"link",section:"Simple story",value:"route:how/check"},"SIMPLE.BOUNDARY":{label:"Boundary",kind:"text",section:"Simple story",value:"Launched is not served. A resolver with no announcing provider answers nothing. Explore and Deploy run on the development network today. Public hosting is not open."},"SIMPLE.CONTEXT":{label:"Context disclosure",kind:"line",section:"Simple story",value:"Context / the earlier agreement path"},"SIMPLE.PATH":{label:"Lifecycle context",kind:"text",section:"Simple story",value:"The full path records the intent, the offer, the agreement, the fulfillment and the receipt."},"SIMPLE.HOME.HREF":{label:"Breadcrumb home link",kind:"link",section:"Simple story",value:"route:zero"},"SIMPLE.NEXT.HREF":{label:"Footer onward link (trace the lifecycle)",kind:"link",section:"Simple story",value:"route:lifecycle"},"CHAPTER.BANNER":{label:"Chapter banner: earlier direction",kind:"text",section:"Chapters",value:"Written for the earlier agreement path, which is no longer the direction. For resolvers today, read What is a resolver."},"CHAPTER.BANNER.HREF":{label:"Chapter banner link target",kind:"link",section:"Chapters",value:"route:resolver"},"CHAPTER.SERIES":{label:`Chapters' series name (the eyebrow says "<name> \xB7 n of 3")`,kind:"line",section:"Chapters",value:"Hire a provider"},"CHAPTER.ASK.TITLE":{label:"Ask Title",kind:"text",section:"How it works chapters",value:"Tell a provider what you need."},"CHAPTER.ASK.INTRO":{label:"Ask Intro",kind:"text",section:"How it works chapters",value:"Every job on DEFXN starts as a signed request, called an intent: the fixed point every later record refers back to."},"CHAPTER.ASK.JOB":{label:"Ask Job",kind:"text",section:"How it works chapters",value:"Make a copy of these files."},"CHAPTER.ASK.CHOICE1":{label:"Ask step 1 title",kind:"text",section:"How it works chapters",value:"Name the exact thing"},"CHAPTER.ASK.CHOICE2":{label:"Ask step 2 title",kind:"text",section:"How it works chapters",value:"Say what done looks like"},"CHAPTER.ASK.CHOICE3":{label:"Ask step 3 title",kind:"text",section:"How it works chapters",value:"Set the limits and sign"},"CHAPTER.ASK.DETAIL1":{label:"Ask step 1 text",kind:"text",section:"How it works chapters",value:"Point at the files by their content ID: a fingerprint computed from the bytes themselves. Change one byte and the ID changes, so nobody can quietly swap in a different version."},"CHAPTER.ASK.DETAIL2":{label:"Ask step 2 text",kind:"text",section:"How it works chapters",value:'Describe a result someone else can check. For a copy, that can be as simple as "the copy has the same content ID". If done cannot be checked, it cannot be verified later.'},"CHAPTER.ASK.DETAIL3":{label:"Ask step 3 text",kind:"text",section:"How it works chapters",value:"Attach the rules that apply and sign the request with your key. The signed intent gets its own content ID, and every later step cites it."},"CHAPTER.WORK.TITLE":{label:"Work Title",kind:"text",section:"How it works chapters",value:"Agree on the same terms."},"CHAPTER.WORK.INTRO":{label:"Work Intro",kind:"text",section:"How it works chapters",value:"A provider answers with an offer. When you both sign the same terms, it becomes an agreement: one record everyone can point to."},"CHAPTER.WORK.CHOICE1":{label:"Work step 1 title",kind:"text",section:"How it works chapters",value:"Your request stays fixed"},"CHAPTER.WORK.CHOICE2":{label:"Work step 2 title",kind:"text",section:"How it works chapters",value:"The provider proposes terms"},"CHAPTER.WORK.DETAIL1":{label:"Work step 1 text",kind:"text",section:"How it works chapters",value:"The provider never edits your intent. Their offer cites its content ID, so the offer is always attached to exactly what you asked for."},"CHAPTER.WORK.DETAIL2":{label:"Work step 2 text",kind:"text",section:"How it works chapters",value:"The offer says what they will do, on what terms, and what evidence they will hand back. It is signed, so it is attributable, but it is still only a proposal, not proof they have the capacity."},"CHAPTER.WORK.JOIN":{label:"Work Join",kind:"text",section:"How it works chapters",value:"The same job. The same rules."},"CHAPTER.CHECK.TITLE":{label:"Check Title",kind:"text",section:"How it works chapters",value:"Check the result."},"CHAPTER.CHECK.INTRO":{label:"Check Intro",kind:"text",section:"How it works chapters",value:"Finishing the job and checking it are separate steps. The provider returns a result with evidence. A named checker compares it with the agreement, and approvers chosen for this one decision sign off on the outcome."},"CHAPTER.CHECK.CHOICE1":{label:"Check step 1 title",kind:"text",section:"How it works chapters",value:"Start from the agreement"},"CHAPTER.CHECK.CHOICE2":{label:"Check step 2 title",kind:"text",section:"How it works chapters",value:"The provider submits a fulfillment"},"CHAPTER.CHECK.CHOICE3":{label:"Check step 3 title",kind:"text",section:"How it works chapters",value:"A checker and authority decide"},"CHAPTER.CHECK.DETAIL1":{label:"Check step 1 text",kind:"text",section:"How it works chapters",value:"The result is compared with the accepted terms, not with the provider's own description of what they did."},"CHAPTER.CHECK.DETAIL2":{label:"Check step 2 text",kind:"text",section:"How it works chapters",value:"This signed record cites the agreement, what went in and what came out. The signature proves who submitted it and that it is unaltered, not that it is correct."},"CHAPTER.CHECK.DETAIL3":{label:"Check step 3 text",kind:"text",section:"How it works chapters",value:"A checker evaluates the result, and approvers chosen by the active policy for this one decision sign off once a threshold is met. The outcome is recorded as a receipt citing the fulfillment."},"CHAPTER.ASK.RECORD.LABEL":{label:"Ask record label",kind:"line",section:"How it works chapters",value:"THE SIGNED INTENT / EXAMPLE"},"CHAPTER.ASK.RECORD":{label:'Ask record rows (one "name: meaning" per line; "[1] " lights a row for choice 1)',kind:"text",section:"How it works chapters",value:`[1] Snapshot: The exact files, by content ID
[2] Outcome: What the finished copy must match
[3] Policy: The rules and limits that apply
[3] Signed by: You, the client
[3] Produces: An intent ID that offers must cite`},"CHAPTER.ASK.NOW":{label:"Ask true now",kind:"text",section:"How it works chapters",value:"One signed, addressable request exists."},"CHAPTER.ASK.NOT":{label:"Ask not yet true",kind:"text",section:"How it works chapters",value:"No provider has committed and no work has happened."},"CHAPTER.WORK.RECORD.LABEL":{label:"Work record label",kind:"line",section:"How it works chapters",value:"THE AGREEMENT / AN EARLIER-PATH TRANSFER RECORD"},"CHAPTER.WORK.RECORD":{label:'Work record rows (one "name: meaning" per line; "[1] " lights a row for choice 1)',kind:"text",section:"How it works chapters",value:`kind: A signed agreement (flux.fabric-transfer.v1)
[1] inputCid: What you asked to move
[2] recipientId: Who receives it
[2] asset, amount: The terms on offer
[3] nextSequence: The input's next version
[3] cid: SHA-256 of the signed record`},"CHAPTER.WORK.NOW":{label:"Work true now",kind:"text",section:"How it works chapters",value:"Both sides hold one inspectable set of terms."},"CHAPTER.WORK.NOT":{label:"Work not yet true",kind:"text",section:"How it works chapters",value:"Accepted terms do not prove the work happened."},"CHAPTER.CHECK.RECORD.LABEL":{label:"Check record label",kind:"line",section:"How it works chapters",value:"THE FULFILLMENT / AN EARLIER-PATH TRANSFER RECORD"},"CHAPTER.CHECK.RECORD":{label:'Check record rows (one "name: meaning" per line; "[1] " lights a row for choice 1)',kind:"text",section:"How it works chapters",value:`kind: A signed fulfillment (flux.fabric-transfer.v1)
[1] agreementCid: The terms it is checked against
[2] inputCid, outputCid: What went in and what came out
[2] signatureB64: The provider's Ed25519 signature
[3] cid: What the receipt points back to`},"CHAPTER.CHECK.NOW":{label:"Check true now",kind:"text",section:"How it works chapters",value:"One rule-bound outcome, traceable back to the request."},"CHAPTER.CHECK.NOT":{label:"Check not yet true",kind:"text",section:"How it works chapters",value:"A receipt is not universal truth, a legal settlement, or a payment."},"CHAPTER.CHECK.RESULT":{label:"Check heading",kind:"line",section:"How it works chapters",value:"A result, with its evidence."},"CHAPTER.ASK.WHY1.TITLE":{label:"Ask why 1 title",kind:"line",section:"How it works chapters",value:"Addresses, not locations"},"CHAPTER.ASK.WHY1.TEXT":{label:"Ask why 1 text",kind:"text",section:"How it works chapters",value:"DEFXN refers to data by what it is, not where it is stored. A server link can change or disappear. A content ID always means the same bytes."},"CHAPTER.ASK.WHY2.TITLE":{label:"Ask why 2 title",kind:"line",section:"How it works chapters",value:"Nobody is committed yet"},"CHAPTER.ASK.WHY2.TEXT":{label:"Ask why 2 text",kind:"text",section:"How it works chapters",value:"An intent is an open request. No provider has promised anything and no work has happened. That changes only when you accept an offer."},"CHAPTER.ASK.WHY3.TITLE":{label:"Ask why 3 title",kind:"line",section:"How it works chapters",value:"Your request travels with the work"},"CHAPTER.ASK.WHY3.TEXT":{label:"Ask why 3 text",kind:"text",section:"How it works chapters",value:"The offer, the agreement, the result and the receipt all cite this intent, so anyone can follow the trail back to what you actually asked for."},"CHAPTER.WORK.CHOICE3":{label:"Work step 3 title",kind:"line",section:"How it works chapters",value:"Both sides sign one agreement"},"CHAPTER.WORK.DETAIL3":{label:"Work step 3 text",kind:"text",section:"How it works chapters",value:"Accepting turns the matching request and offer into an agreement record. Its ID is a hash of the exact signed terms, so changing any term later makes it a different agreement."},"CHAPTER.WORK.WHY1.TITLE":{label:"Work why 1 title",kind:"line",section:"How it works chapters",value:"Every chain runs in its own lane"},"CHAPTER.WORK.WHY1.TEXT":{label:"Work why 1 text",kind:"text",section:"How it works chapters",value:"There is no single global queue. Each party writes to its own chain, so unrelated work never waits behind yours, unlike one shared queue that every record has to wait in."},"CHAPTER.WORK.WHY2.TITLE":{label:"Work why 2 title",kind:"line",section:"How it works chapters",value:"Terms that cannot drift"},"CHAPTER.WORK.WHY2.TEXT":{label:"Work why 2 text",kind:"text",section:"How it works chapters",value:'Because records are addressed by their content, "the agreement" always means these exact signed bytes. Both sides, and any checker, start from the same document.'},"CHAPTER.WORK.WHY3.TITLE":{label:"Work why 3 title",kind:"line",section:"How it works chapters",value:"Agreed is not done"},"CHAPTER.WORK.WHY3.TEXT":{label:"Work why 3 text",kind:"text",section:"How it works chapters",value:"An agreement fixes what the result will be checked against. It does not prove the work happened or that anyone has been paid. That is the next step."},"CHAPTER.CHECK.WHY1.TITLE":{label:"Check why 1 title",kind:"line",section:"How it works chapters",value:"Trust is decided before"},"CHAPTER.CHECK.WHY1.TEXT":{label:"Check why 1 text",kind:"text",section:"How it works chapters",value:"A signature proves who submitted a result, not that the result is right. The result is judged against the agreement both sides signed before the work began."},"CHAPTER.CHECK.WHY2.TITLE":{label:"Check why 2 title",kind:"line",section:"How it works chapters",value:"Authority for one decision only"},"CHAPTER.CHECK.WHY2.TEXT":{label:"Check why 2 text",kind:"text",section:"How it works chapters",value:"The approvers are selected for this one object and step. They can certify only that step, publish the evidence, and then their mandate ends."},"CHAPTER.CHECK.WHY3.TITLE":{label:"Check why 3 title",kind:"line",section:"How it works chapters",value:"Signed, then stored"},"CHAPTER.CHECK.WHY3.TEXT":{label:"Check why 3 text",kind:"text",section:"How it works chapters",value:"The resolver signs the result. That signature is the result. Copies go to other peers, which store it without redoing the work. Anyone can check it later by walking the signatures."}}});
;
/* ---- js/content/manifests/concept.js ---- */
ArkManifest.define({id:"concept",title:"Operating model",route:"/concept",group:"page",meta:{},fields:{EYEBROW:{label:"Eyebrow",kind:"line",section:"Page",value:"FLUX PROTOCOL"},TITLE:{label:"Heading",kind:"line",section:"Page",value:"The operating model."},DECK:{label:"Intro",kind:"text",section:"Page",value:"DEFXN is the kernel of the grid. FXN is its first chain and that chain\u2019s coin. Pick a question: what your network shares, how an agreement closes, or who may approve a change. Each page gives the answer, its limits and its source evidence."},ICEBERG:{label:"Iceberg description (for screen readers)",kind:"text",section:"Page",value:"A rotating particle form; decorative."},RAIL:{label:"Name of the links beside the page (for screen readers)",kind:"line",section:"Page",value:"Continue exploring"},"BACK.HREF":{label:"Breadcrumb: Overview link",kind:"link",section:"Page",value:"route:about"}}});
;
/* ---- js/content/manifests/about.js ---- */
ArkManifest.define({id:"about",title:"DEFXN overview",route:"/about",group:"page",meta:{next:"concept"},fields:{EYEBROW:{label:"Eyebrow",kind:"line",section:"Page",value:"DEFXN / OVERVIEW"},TITLE:{label:"Heading",kind:"line",section:"Page",value:"Overview."},DECK:{label:"Intro",kind:"text",section:"Page",value:"What it is: DEFXN is the kernel. FXN is its first chain and that chain's coin. A resolver turns signed records into a result anyone can check. What you do: Initiate FXN ID, sign records, use resolvers. What you get back: signed receipts and results you can check. Status: the FXN ID gate, the name gateway, the DNS gateway and the bundle upload door are live on the old infra. The new devnet is not deployed."},CONTEXT:{label:"Supporting explanation disclosure",kind:"line",section:"Page",value:"Under the hood / the three layers"},"MODEL.TITLE":{label:"Model label",kind:"line",section:"Page",value:"Three bounded layers"},"MODEL.TEXT":{label:"Model summary",kind:"line",section:"Page",value:"The directory finds the network. The chain admits signed records. Each group can change only its own scope."},ACTION:{label:"Primary action",kind:"line",section:"Links",value:"Explore resolutions"},"ACTION.HREF":{label:"Primary action link",kind:"link",section:"Links",value:"route:resolutions"},"BOUNDARY.TITLE":{label:"Visible source boundary",kind:"line",section:"Status",value:"Core paths exist in source. Production activation and packaged releases remain unverified."},REFERENCE:{label:"Reference disclosure",kind:"line",section:"Status",value:"Evidence & verification"},"POINT1.TITLE":{label:"Heading",kind:"line",section:"Point 1",value:"Directory: address a network."},"POINT1.TEXT":{label:"Text",kind:"text",section:"Point 1",value:"Each network gets a named ID so it can be found. Today that partitions miner presence only. Isolating accounts, records and treasury is not built yet."},"POINT2.TITLE":{label:"Heading",kind:"line",section:"Point 2",value:"Chains: one signed chain per identity."},"POINT2.TEXT":{label:"Text",kind:"text",section:"Point 2",value:"Every identity writes to its own append-only chain, and every resolver runs its own. A record is admitted if its signature verifies, it extends the signer\u2019s head, and it fits the grammar of the resolver it names."},"POINT3.TITLE":{label:"Heading",kind:"line",section:"Point 3",value:"Governance: identify who may change what."},"POINT3.TEXT":{label:"Text",kind:"text",section:"Point 3",value:"Authority is tied to a named scope and threshold. Network governance cannot take over the shared base, and base policy cannot take over a network."},"POINT4.TITLE":{label:"Heading",kind:"line",section:"Point 4",value:"What the source establishes."},"POINT4.TEXT":{label:"Text",kind:"text",section:"Point 4",value:"The resolver model is implemented in source: launch and upgrade, shared capabilities with test vectors, grammar checks, and provider proofs. It runs on the development network. The DEFXN miner, network CLI and FXN chain prototype are implemented in source too, and fleet benchmarks are recorded on the stats page. Packaged releases and production activation remain unverified."},"POINT5.TITLE":{label:"Heading",kind:"line",section:"Point 5",value:"How to verify it."},"POINT5.TEXT":{label:"Text",kind:"text",section:"Point 5",value:"Run DEFXN from a trusted source revision, record the miner status response, then inspect the signed records on each holder\u2019s chain. A successful local run proves that environment only. It does not establish production readiness."},NEXT:{label:"Onward link (an arrow is added)",kind:"line",section:"Links",value:"EXPLORE THE DEFXN MODEL"},STATUS:{label:"Status documentation link",kind:"line",section:"Links",value:"READ DEFXN STATUS"},"STATUS.HREF":{label:"Status documentation target",kind:"link",section:"Links",value:"doc:docs/status.md"},ACTION2:{label:"Secondary action",kind:"line",section:"Links",value:"Deploy a resolver"},"ACTION2.HREF":{label:"Secondary action link",kind:"link",section:"Links",value:"route:resolutions/deployments"},"FOOTER.HOME.HREF":{label:"Footer: Home link",kind:"link",section:"Links",value:"route:zero"},"FOOTER.RESOLUTIONS.HREF":{label:"Footer: Resolutions link",kind:"link",section:"Links",value:"route:resolutions"},"FOOTER.EXPLORER.HREF":{label:"Footer: Explorer link",kind:"link",section:"Links",value:"route:explorer"},"FOOTER.DOWNLOAD.HREF":{label:"Footer: Run from source link",kind:"link",section:"Links",value:"route:download"},"PROMISE.LABEL":{label:"Promise label",kind:"line",section:"Promise",value:"WHAT IS NOT BUILT YET"},"PROMISE.TITLE":{label:"Promise heading",kind:"line",section:"Promise",value:"A site as a signed bundle, not a rented server."},"PROMISE.TEXT":{label:"Promise text",kind:"text",section:"Promise",value:"Publishing a site this way is planned. The Bundle Deployer is not released, and public hosting is not established."},"NO1.TITLE":{label:"Heading",kind:"line",section:"Promise",value:"Records, not a database server"},"NO1.TEXT":{label:"Text",kind:"text",section:"Promise",value:"Data is written as signed records on a list per identity, and pinners on other machines keep copies. You do not run a database server for it."},"NO2.TITLE":{label:"Heading",kind:"line",section:"Promise",value:"Nodes serve, not a rented host"},"NO2.TEXT":{label:"Text",kind:"text",section:"Promise",value:"Computers that run the store role serve what you publish. The development fleet does this today. A public network does not exist yet."},"NO3.TITLE":{label:"Heading",kind:"line",section:"Promise",value:"Fees are decided, not set"},"NO3.TEXT":{label:"Text",kind:"text",section:"Promise",value:"Running work will cost FXN. A fee splits between the computers that do the work and a network fund, and the owner\u2019s figure is 65% and 35%. No price is set."},"NO4.TITLE":{label:"Heading",kind:"line",section:"Promise",value:"Your key, not an account"},"NO4.TEXT":{label:"Text",kind:"text",section:"Promise",value:"You sign with a key you hold, so no vendor account stands between you and your records. Nodes still have to run somewhere."},"PILLARS.LABEL":{label:"Pillars label",kind:"line",section:"Pillars",value:"WHAT DEFXN IS"},"PILLAR1.TITLE":{label:"Heading",kind:"line",section:"Pillars",value:"One kernel, many chains"},"PILLAR1.TEXT":{label:"Text",kind:"text",section:"Pillars",value:"DEFXN is the base chain kernel. Network chains such as FXN run on it, and every identity and every resolver has a chain of its own."},"PILLAR2.TITLE":{label:"Heading",kind:"line",section:"Pillars",value:"Everyone signs for themselves"},"PILLAR2.TEXT":{label:"Text",kind:"text",section:"Pillars",value:"Builders, node operators and users each sign their own records. An agreement links the records of the parties to it, and no platform account sits between them."},"PILLAR3.TITLE":{label:"Heading",kind:"line",section:"Pillars",value:"FXN: the first chain and its coin"},"PILLAR3.TEXT":{label:"Text",kind:"text",section:"Pillars",value:"FXN is the first network chain on the kernel, and the kernel itself has no currency. The coin is for settling work and paying the computers that do it. Its supply and release rules are in the dense-wire code, checked 2026-10-24."},"RESOLVE.LABEL":{label:"Resolutions label",kind:"line",section:"Resolutions",value:"RESOLVE YOUR\u2026"},"RESOLVE.TITLE":{label:"Resolutions heading",kind:"line",section:"Resolutions",value:"Twenty ideas for what a resolver can do."},"RESOLVE.ALL":{label:"Link to all resolutions (an arrow is added)",kind:"line",section:"Resolutions",value:"See every resolution"},"RESOLVE.ALL.HREF":{label:"Link to all resolutions target",kind:"link",section:"Resolutions",value:"route:resolutions"},"RESOLVE.GROUP.HREF":{label:"Resolution group tile target",kind:"link",section:"Resolutions",value:"route:resolutions"},"FLOW.LABEL":{label:"Flow label",kind:"line",section:"Flow",value:"HOW A RESOLUTION WORKS"},"FLOW1.TITLE":{label:"Heading",kind:"line",section:"Flow",value:"Resolve"},"FLOW1.TEXT":{label:"Text",kind:"text",section:"Flow",value:"You send a signed record in the resolver\u2019s grammar."},"FLOW2.TITLE":{label:"Heading",kind:"line",section:"Flow",value:"Resolver"},"FLOW2.TEXT":{label:"Text",kind:"text",section:"Flow",value:"A resolver applies its own published grammar and capabilities to your request and signs the result."},"FLOW3.TITLE":{label:"Heading",kind:"line",section:"Flow",value:"Resolution"},"FLOW3.TEXT":{label:"Text",kind:"text",section:"Flow",value:"Other computers store the signed result. Anyone can follow its signatures back and check them."},"FLOW.LINK":{label:"Link to the resolver guide (an arrow is added)",kind:"line",section:"Flow",value:"What is a resolver?"},"FLOW.LINK.HREF":{label:"Link to the resolver guide target",kind:"link",section:"Flow",value:"route:resolver"},"FLOW.TITLE":{label:"Heading: how a resolution works",kind:"line",section:"Page",value:"Send a record. Get a signed result. Check it."},"PILLARS.TITLE":{label:"Heading: what DEFXN is",kind:"line",section:"Page",value:"A kernel, the chains on it, and the people who sign."},"CLOSE.TITLE":{label:"Closing heading",kind:"line",section:"Page",value:"See the resolver chains."}}});
;
