ArkManifest.define({id:"purpose",title:"Networks",route:"/concept/purpose",group:"theory",meta:{placement:"row",next:"concept/depth",docs:"docs/operators/networks.md",back:"concept"},fields:{EYEBROW:{label:"Eyebrow",kind:"line",section:"Page",value:"FLUX PROTOCOL / NETWORKS"},TITLE:{label:"Heading",kind:"line",section:"Page",value:"What does a DEFXN network do today?"},DECK:{label:"Intro",kind:"text",section:"Page",value:"A named network is a name that miners can start with. Miners that start with the same name announce themselves in the same place, so they can find each other. That is all a network separates today. What it does not separate is listed under Evidence."},CTA:{label:"Link on the theory page",kind:"line",section:"Links",value:"UNDERSTAND NETWORK SCOPE"},"POINT1.TITLE":{label:"Heading",kind:"line",section:"Point 1",value:"The current boundary is presence."},"POINT1.TEXT":{label:"Text",kind:"text",section:"Point 1",value:"Miners started with the same network ID announce themselves in the same place. This helps them find each other. It does not admit anyone, give anyone authority, or show that a miner can be trusted."},"POINT2.TITLE":{label:"Heading",kind:"line",section:"Point 2",value:"Creation and selection use one directory primitive."},"POINT2.TEXT":{label:"Text",kind:"text",section:"Point 2",value:"The command flux-network network create <name> returns a new network ID, or the ID of an existing network with that name. A miner started with that ID joins that network\u2019s place."},"POINT3.TITLE":{label:"Heading",kind:"line",section:"Point 3",value:"Directory results are best-effort discovery."},"POINT3.TEXT":{label:"Text",kind:"text",section:"Point 3",value:"A network that lists no miners may still exist. Its miners may be idle or not yet found. The list is not a complete record of members."},"POINT4.TITLE":{label:"Heading",kind:"line",section:"Point 4",value:"Governance is a separate decision."},"POINT4.TEXT":{label:"Text",kind:"text",section:"Point 4",value:"Choosing a network ID does not create a DAO (a group of signers who vote), admit an identity, or give anyone authority. Each of those needs its own policy and evidence."},"POINT5.TITLE":{label:"Heading",kind:"line",section:"Point 5",value:"Named examples still need evidence."},"POINT5.TEXT":{label:"Text",kind:"text",section:"Point 5",value:"This site calls a network active only when it has a network ID, a source or manifest location, an observation date and an artifact you can inspect."},"STATUS.TITLE":{label:"Status heading",kind:"line",section:"Evidence",value:"Status / Partial"},"STATUS.TEXT":{label:"Status text",kind:"text",section:"Evidence",value:"The create and list commands, and the shared place where miners announce themselves, are built in source. No complete independent live run is registered in this audit."},"LIMIT.TITLE":{label:"Limitation heading",kind:"line",section:"Evidence",value:"Current limitation"},"LIMIT.TEXT":{label:"Limitation text",kind:"text",section:"Evidence",value:"A named network currently isolates only miner-presence discovery, which is how miners find each other. A network ID does not scope accounts, identities, DAOs, records or treasuries. It is not an authoritative membership list or security boundary. Do not use it as one."},EVIDENCE:{label:"Canonical evidence link",kind:"line",section:"Links",value:"READ THE NETWORK OPERATOR GUIDE"},NEXT:{label:"Onward link (an arrow is added)",kind:"line",section:"Links",value:"NEXT QUESTION: HOW AN AGREEMENT IS CHECKED"},SETUP:{label:"Setup link (in Evidence)",kind:"line",section:"Links",value:"CREATE OR JOIN A NETWORK"},"SETUP.HREF":{label:"Setup link (in Evidence): where it goes",kind:"link",section:"Links",value:"route:deploy"},BACK:{label:"Link back to the theory (an arrow is added)",kind:"line",section:"Links",value:"OPERATING MODEL"}}});
;
/* ---- js/content/manifests/depth.js ---- */
ArkManifest.define({id:"depth",title:"Checkable agreements",route:"/concept/depth",group:"theory",meta:{placement:"row",next:"lifecycle",docs:"docs/protocol/agreements.md",back:"concept"},fields:{EYEBROW:{label:"Eyebrow",kind:"line",section:"Page",value:"FLUX PROTOCOL / AGREEMENTS"},TITLE:{label:"Heading",kind:"line",section:"Page",value:"How does an agreement become checkable?"},DECK:{label:"Intro",kind:"text",section:"Page",value:"One signed trail records what was requested, offered, accepted, produced and checked. Each record sits on its writer\u2019s own chain. It cites the record before it by CID, a fingerprint of that record\u2019s bytes. An auditor can follow the trail across every party\u2019s chain."},CTA:{label:"Link on the theory page",kind:"line",section:"Links",value:"FOLLOW ONE AGREEMENT"},"POINT1.TITLE":{label:"Heading",kind:"line",section:"Point 1",value:"Intent states the need."},"POINT1.TEXT":{label:"Text",kind:"text",section:"Point 1",value:"The requester signs the exact outcome they want. The request can now be found by its address, but no provider has promised anything."},"POINT2.TITLE":{label:"Heading",kind:"line",section:"Point 2",value:"Offer answers that exact intent."},"POINT2.TEXT":{label:"Text",kind:"text",section:"Point 2",value:"A provider proposes terms and cites the request by its CID. Anyone can inspect the offer. It is not an agreement until the terms are accepted."},"POINT3.TITLE":{label:"Heading",kind:"line",section:"Point 3",value:"Agreement records the accepted match."},"POINT3.TEXT":{label:"Text",kind:"text",section:"Point 3",value:"The parties sign the accepted terms, each on their own chain. Unrelated work does not wait behind this agreement."},"POINT4.TITLE":{label:"Heading",kind:"line",section:"Point 4",value:"Fulfillment shows the work."},"POINT4.TEXT":{label:"Text",kind:"text",section:"Point 4",value:"The provider links evidence of the result to the agreement. Recording this does not show that every other system has settled."},"POINT5.TITLE":{label:"Heading",kind:"line",section:"Point 5",value:"Receipt records the verification outcome."},"POINT5.TEXT":{label:"Text",kind:"text",section:"Point 5",value:"The party who verifies closes the trail under named checker and authority rules. A receipt is evidence of that decision. It is not universal truth or a legal settlement."},"STATUS.TITLE":{label:"Status heading",kind:"line",section:"Evidence",value:"Status / Partial"},"STATUS.TEXT":{label:"Status text",kind:"text",section:"Evidence",value:"The path from request to receipt, and the agreements resolver\u2019s inspection contract, are built in source. No complete public production run is registered here."},"LIMIT.TITLE":{label:"Limitation heading",kind:"line",section:"Evidence",value:"What this does not establish"},"LIMIT.TEXT":{label:"Limitation text",kind:"text",section:"Evidence",value:"The lifecycle does not by itself prove automatic admission, payment, production use, or that a signed claim is true."},EVIDENCE:{label:"Canonical evidence link",kind:"line",section:"Links",value:"READ THE AGREEMENT GUIDE"},NEXT:{label:"Onward link (an arrow is added)",kind:"line",section:"Links",value:"FOLLOW THE FIVE STAGES"},BACK:{label:"Link back to the theory (an arrow is added)",kind:"line",section:"Links",value:"OPERATING MODEL"}}});
;
/* ---- js/content/manifests/practice.js ---- */
ArkManifest.define({id:"practice",title:"Authority",route:"/concept/practice",group:"theory",meta:{placement:"row",next:"dao",docs:"docs/protocol/authority.md",back:"concept"},fields:{EYEBROW:{label:"Eyebrow",kind:"line",section:"Page",value:"FLUX PROTOCOL / AUTHORITY"},TITLE:{label:"Heading",kind:"line",section:"Page",value:"Who can approve a change?"},DECK:{label:"Intro",kind:"text",section:"Page",value:"For each change, the policy names who may approve it. When enough of them sign, their signatures are published as evidence. Their authority ends with that change."},CTA:{label:"Link on the theory page",kind:"line",section:"Links",value:"UNDERSTAND BOUNDED AUTHORITY"},"POINT1.TITLE":{label:"Heading",kind:"line",section:"Point 1",value:"1. Derive the eligible cell."},"POINT1.TEXT":{label:"Text",kind:"text",section:"Point 1",value:"Four inputs tie the approving group to this one change: the object\u2019s CID, its next sequence number, the root of the authority registry and the CID of the active policy."},"POINT2.TITLE":{label:"Heading",kind:"line",section:"Point 2",value:"2. Apply the policy threshold."},"POINT2.TEXT":{label:"Text",kind:"text",section:"Point 2",value:"The active policy says how many approvals are needed. A public claim must name that policy and show the approvals collected."},"POINT3.TITLE":{label:"Heading",kind:"line",section:"Point 3",value:"3. Publish the certificate."},"POINT3.TEXT":{label:"Text",kind:"text",section:"Point 3",value:"The published certificate names the object, the change, the policy, the eligible group and the approvals. Another participant can inspect the decision."},"POINT4.TITLE":{label:"Heading",kind:"line",section:"Point 4",value:"4. Dissolve the cell."},"POINT4.TEXT":{label:"Text",kind:"text",section:"Point 4",value:"After the decision, the group has no standing mandate. The next change picks its approvers again from its own inputs."},"POINT5.TITLE":{label:"Heading",kind:"line",section:"Point 5",value:"5. Enforce the non-authority boundary."},"POINT5.TEXT":{label:"Text",kind:"text",section:"Point 5",value:"A certificate for one object and sequence number cannot approve another object, network, policy or change. Being on the mesh does not give authority."},"STATUS.TITLE":{label:"Status heading",kind:"line",section:"Evidence",value:"Status / Partial"},"STATUS.TEXT":{label:"Status text",kind:"text",section:"Evidence",value:"The structure of authority policy and its thresholds are documented in source. Independent production use is not verified."},"LIMIT.TITLE":{label:"Limitation heading",kind:"line",section:"Evidence",value:"What the cell cannot authorize"},"LIMIT.TEXT":{label:"Limitation text",kind:"text",section:"Evidence",value:"An approving group cannot reuse its certificate for another change, replace mesh-operations governance, or govern a network DAO. A signature does not make a claim true."},EVIDENCE:{label:"Canonical evidence link",kind:"line",section:"Links",value:"READ THE AUTHORITY GUIDE"},NEXT:{label:"Onward link (an arrow is added)",kind:"line",section:"Links",value:"SEE WHO CAN CHANGE WHAT"},BACK:{label:"Link back to the theory (an arrow is added)",kind:"line",section:"Links",value:"OPERATING MODEL"}}});
;
/* ---- js/content/manifests/notes.js ---- */
ArkManifest.define({id:"notes",title:"Activation",route:"/concept/notes",group:"theory",meta:{placement:"rail",next:"concept/studio",docs:"docs/protocol/governance.md",back:"concept"},fields:{EYEBROW:{label:"Eyebrow",kind:"line",section:"Page",value:"FLUX PROTOCOL / ACTIVATION"},TITLE:{label:"Heading",kind:"line",section:"Page",value:"When does an approved change become active?"},DECK:{label:"Intro",kind:"text",section:"Page",value:"Approval records who agreed, under a policy. Activation is a separate step: it applies the approved change after its readiness and safety checks pass."},CTA:{label:"Link on the theory page",kind:"line",section:"Links",value:"SEPARATE APPROVAL FROM ACTIVATION"},"POINT1.TITLE":{label:"Heading",kind:"line",section:"Point 1",value:"Approval answers who consented."},"POINT1.TEXT":{label:"Text",kind:"text",section:"Point 1",value:"The decision record names the policy, the eligible people, the number of approvals needed and the approvals collected. It does not show that the change is running."},"POINT2.TITLE":{label:"Heading",kind:"line",section:"Point 2",value:"Activation answers what was applied."},"POINT2.TEXT":{label:"Text",kind:"text",section:"Point 2",value:"Activation evidence must name the approved action, the target environment, the revision applied, who or what applied it, and when it was observed."},"POINT3.TITLE":{label:"Heading",kind:"line",section:"Point 3",value:"Readiness gates remain independent."},"POINT3.TEXT":{label:"Text",kind:"text",section:"Point 3",value:"Three checks are separate from the approval signatures: readiness on independent hosts, hostile testing, and signed soak evidence (a long run under load). Do not infer one from the others."},"POINT4.TITLE":{label:"Heading",kind:"line",section:"Point 4",value:"Pause and unpause are intentionally asymmetric."},"POINT4.TEXT":{label:"Text",kind:"text",section:"Point 4",value:"In the source policy, pausing is easier than unpausing. That lowers the risk of recovery mistakes. It does not show that any production system is active."},"POINT5.TITLE":{label:"Heading",kind:"line",section:"Point 5",value:"Missing evidence stays unverified."},"POINT5.TEXT":{label:"Text",kind:"text",section:"Point 5",value:"If the revision, environment, observation time or readiness evidence is missing, report activation as Unverified. Do not treat signatures as proof that a change is live."},"STATUS.TITLE":{label:"Status heading",kind:"line",section:"Evidence",value:"Status / Unverified"},"STATUS.TEXT":{label:"Status text",kind:"text",section:"Evidence",value:"Independent production activation is not established by the evidence registered in this repository."},"LIMIT.TITLE":{label:"Limitation heading",kind:"line",section:"Evidence",value:"Do not infer"},"LIMIT.TEXT":{label:"Limitation text",kind:"text",section:"Evidence",value:"Do not infer that a change is running, paid for or ready for production from a full set of approval signatures."},EVIDENCE:{label:"Canonical evidence link",kind:"line",section:"Links",value:"READ THE GOVERNANCE GUIDE"},NEXT:{label:"Onward link (an arrow is added)",kind:"line",section:"Links",value:"NEXT QUESTION: HOW TO VERIFY A NETWORK"},GOVERNANCE:{label:"Governance link (in Evidence)",kind:"line",section:"Links",value:"SEE WHO CAN CHANGE WHAT"},"GOVERNANCE.HREF":{label:"Governance link (in Evidence): where it goes",kind:"link",section:"Links",value:"route:dao"},BACK:{label:"Link back to the theory (an arrow is added)",kind:"line",section:"Links",value:"OPERATING MODEL"}}});
;
/* ---- js/content/manifests/studio.js ---- */
ArkManifest.define({id:"studio",title:"Network evidence",route:"/concept/studio",group:"theory",meta:{placement:"rail",next:"concept/spec",docs:"docs/evidence/registry.md",back:"concept"},fields:{EYEBROW:{label:"Eyebrow",kind:"line",section:"Page",value:"DEFXN / NETWORK EVIDENCE"},TITLE:{label:"Heading",kind:"line",section:"Page",value:"How do you check a named network?"},DECK:{label:"Intro",kind:"text",section:"Page",value:"A network name or a directory row is not enough evidence. To verify a network, record the command and its result, the network ID, the source revision, which processes or hosts took part, when you looked, and what the network ID does not separate today."},CTA:{label:"Link on the theory page",kind:"line",section:"Links",value:"INSPECT NETWORK EVIDENCE"},"POINT1.TITLE":{label:"Heading",kind:"line",section:"Point 1",value:"Record the source revision."},"POINT1.TEXT":{label:"Text",kind:"text",section:"Point 1",value:"Record the exact flux-network and flux-miner revisions and versions. A command copied from another release is not evidence for the build you installed."},"POINT2.TITLE":{label:"Heading",kind:"line",section:"Point 2",value:"Record the network ID and command result."},"POINT2.TEXT":{label:"Text",kind:"text",section:"Point 2",value:"Keep the output of create-or-select, the network ID you chose, the peer settings, and whether the directory already had that entry."},"POINT3.TITLE":{label:"Heading",kind:"line",section:"Point 3",value:"Observe from another process or host."},"POINT3.TEXT":{label:"Text",kind:"text",section:"Point 3",value:"Show a miner being found from outside the process that announced it. A setting on your own machine does not prove participation."},"POINT4.TITLE":{label:"Heading",kind:"line",section:"Point 4",value:"Keep discovery and authority separate."},"POINT4.TEXT":{label:"Text",kind:"text",section:"Point 4",value:"Directory output shows who has announced themselves. It does not prove admission, trusted membership, a DAO roster or authority."},"POINT5.TITLE":{label:"Heading",kind:"line",section:"Point 5",value:"Publish the limitation beside the result."},"POINT5.TEXT":{label:"Text",kind:"text",section:"Point 5",value:"Print the limit next to every network result: what the network ID does not separate today. The Networks page lists it."},"STATUS.TITLE":{label:"Status heading",kind:"line",section:"Evidence",value:"Status / Partial"},"STATUS.TEXT":{label:"Status text",kind:"text",section:"Evidence",value:"The network commands are built in source. A complete independent run that creates a network and joins it is still pending."},"LIMIT.TITLE":{label:"Limitation heading",kind:"line",section:"Evidence",value:"Reference deployments"},"LIMIT.TEXT":{label:"Limitation text",kind:"text",section:"Evidence",value:"Named networks stay unverified until their IDs, sources, observation dates and artifacts are registered. The evidence registry tracks this as CAP-003."},EVIDENCE:{label:"Canonical evidence link",kind:"line",section:"Links",value:"OPEN THE EVIDENCE REGISTRY"},NEXT:{label:"Onward link (an arrow is added)",kind:"line",section:"Links",value:"NEXT QUESTION: WHAT IS MEASURED"},LIMITS:{label:"Network limits link (in Evidence)",kind:"line",section:"Links",value:"WHAT A NETWORK ID DOES NOT ISOLATE"},"LIMITS.HREF":{label:"Network limits link (in Evidence): where it goes",kind:"link",section:"Links",value:"route:concept/purpose"},SETUP:{label:"Setup link (in Evidence)",kind:"line",section:"Links",value:"CREATE OR JOIN A NETWORK"},"SETUP.HREF":{label:"Setup link (in Evidence): where it goes",kind:"link",section:"Links",value:"route:deploy"},BACK:{label:"Link back to the theory (an arrow is added)",kind:"line",section:"Links",value:"OPERATING MODEL"}}});
;
/* ---- js/content/manifests/spec.js ---- */
ArkManifest.define({id:"spec",title:"Benchmarks",route:"/concept/spec",group:"theory",meta:{placement:"rail",next:"stats",docs:"docs/protocol/benchmarks.md",back:"concept"},fields:{EYEBROW:{label:"Eyebrow",kind:"line",section:"Page",value:"FLUX PROTOCOL / BENCHMARKS"},TITLE:{label:"Heading",kind:"line",section:"Page",value:"What is actually measured?"},DECK:{label:"Intro",kind:"text",section:"Page",value:"Three of the six verified records, each with where and when it ran: 46,178 swaps a second in a batched auction on one machine with no network (2026-10-10); 61,398 operations a second applied on every replica of eight fleet servers plus one local node (2026-10-08); and 11,318 operations a second accepted on six public nodes with live 4-of-6 approval signing (2026-10-09/10). None is a production result, and none is added to another."},CTA:{label:"Link on the theory page",kind:"line",section:"Links",value:"REVIEW THE EVIDENCE STANDARD"},"POINT1.TITLE":{label:"Heading",kind:"line",section:"Point 1",value:"Current conclusion: verified at stated boundaries."},"POINT1.TEXT":{label:"Text",kind:"text",section:"Point 1",value:"A record is promoted only when its evidence record names the workload, the machine or fleet, the date and the method beside the number. Six records meet that today. A local result is not a fleet result, a fleet result is not production, and a rate in one unit is never compared with a rate in another."},"POINT2.TITLE":{label:"Heading",kind:"line",section:"Point 2",value:"Comparable tests must share a mode."},"POINT2.TEXT":{label:"Text",kind:"text",section:"Point 2",value:"Sequential, concurrent, local-process, multi-host, and rate-limited external runs answer different questions. They must not be collapsed into one multiplier."},"POINT3.TITLE":{label:"Heading",kind:"line",section:"Point 3",value:"Incomplete runs remain incomplete."},"POINT3.TEXT":{label:"Text",kind:"text",section:"Point 3",value:"A smoke sample or unfinished soak cannot be presented as sustained performance, a ceiling, or a production-readiness result."},"POINT4.TITLE":{label:"Heading",kind:"line",section:"Point 4",value:"Every result needs its conditions."},"POINT4.TEXT":{label:"Text",kind:"text",section:"Point 4",value:"A publishable record names hardware, operating system, network conditions, dataset, warm-up, repetitions, aggregation method, units, uncertainty, and known limitations."},"POINT5.TITLE":{label:"Heading",kind:"line",section:"Point 5",value:"Raw artifacts come before the headline."},"POINT5.TEXT":{label:"Text",kind:"text",section:"Point 5",value:"The evidence registry must link the raw result and digest before a public page can promote a measurement from Unverified to Live or Partial."},"POINT6.TITLE":{label:"Heading",kind:"line",section:"Point 6",value:"Verified on one machine."},"POINT6.TEXT":{label:"Text",kind:"text",section:"Point 6",value:"BENCH-006 (Local, verified): 279,269 ops/s certified sharded segment application, 5.47\xD7 the 51,065 ops/s per-operation admission; one local Apple M-series machine, 2026-10-08; no eight-node projection. BENCH-013 (Local, verified): every operation in its own unit, one machine, no network, median of 5 reps, 2026-10-10: 13,476 same-shard transfers/s, 6,799 cross-shard transfers/s, 46,178 swaps/s in a batched auction. BENCH-015 (Local, verified): 4,425 swaps/s at 1 connection and ~31,000 at 1,000, one local node over loopback, unbacked, zero-confirmation store, 2026-10-15; not a fleet figure."},"POINT7.TITLE":{label:"Heading",kind:"line",section:"Point 7",value:"Verified on the fleet."},"POINT7.TEXT":{label:"Text",kind:"text",section:"Point 7",value:"BENCH-007 (Fleet, verified application boundary): 61,398 all-replica logical ops/s, bounded by the slowest replica; one 20,000-operation segment applied on eight VPS nodes plus one local node, 180,000/180,000 applied, zero errors, 2026-10-08; broadcast and durable segment commit excluded. BENCH-009 (Fleet, verified): 11,318 accepted ops/s with live 4-of-6 cross-node certified-segment signing, against 11,169 with no approval; six public nodes, 300 s per configuration, zero failures, 2026-10-09/10; acceptance does not imply inclusion in a signed segment. BENCH-012 (Fleet, verified): 15,360 swaps in 60 batches of 256, broadcast to 10 live replicas, 60/60 audits passed, 13.874 ms batch latency, 2026-10-10; the unpipelined broadcast dominates end to end."},"STATUS.TITLE":{label:"Status heading",kind:"line",section:"Evidence",value:"Status / Six records verified"},"STATUS.TEXT":{label:"Status text",kind:"text",section:"Evidence",value:"Six benchmark records are verified, each at its own stated boundary. Each number, with its machine or fleet and date, is under Step by step. What is still not verified is under Evidence."},"LIMIT.TITLE":{label:"Limitation heading",kind:"line",section:"Evidence",value:"No cross-system conclusion"},"LIMIT.TEXT":{label:"Limitation text",kind:"text",section:"Evidence",value:"Still not verified. BENCH-001 (Partial): a 10,000-transfer real-fleet run of the directory registry did not complete. BENCH-002 (Partial): the gap between the writer-contention model and the fleet's multi-second p50 is not yet explained. BENCH-003 (Partial): the Rust rebuild's fleet figures; membership is not persisted across restarts. BENCH-004 (Partial): 12,403 accepted ops/s over 303.152 seconds from one arm64 client, not cumulative growth or replica-certified durability. BENCH-005 (Superseded in part): one million accepted durable ops/s remains unverified. BENCH-008 (Historical): the six-node baseline, superseded. BENCH-011 (Partial): 82,863 signed transfers/s on all 10 nodes; raw JSON and source revision still to be attached. BENCH-014 (Partial): 17 claims/s durable on two fleet nodes over real WAN, not the 3-of-9 shape, not on production. No verified record is a throughput, latency or scale claim for production, and none is a comparison with an external chain."},EVIDENCE:{label:"Canonical evidence link",kind:"line",section:"Links",value:"READ THE BENCHMARK STANDARD"},NEXT:{label:"Onward link (an arrow is added)",kind:"line",section:"Links",value:"SEE THE MEASURED RESULTS"},RUN:{label:"Run-it-yourself link (in Evidence)",kind:"line",section:"Links",value:"RUN DEFXN FROM SOURCE"},"RUN.HREF":{label:"Run-it-yourself link (in Evidence): where it goes",kind:"link",section:"Links",value:"route:download"},BACK:{label:"Link back to the theory (an arrow is added)",kind:"line",section:"Links",value:"OPERATING MODEL"},STATS:{label:"Live fleet dashboard link",kind:"line",section:"Links",value:"See the measured results on the fleet dashboard"},"STATS.HREF":{label:"Live fleet dashboard target",kind:"link",section:"Links",value:"route:stats"},GPU:{label:"GPU measurement link",kind:"line",section:"Links",value:"Why the GPU does nothing here"},"GPU.HREF":{label:"GPU measurement target",kind:"link",section:"Links",value:"route:stats/gpu"},LEDGER:{label:"Finance resolver link",kind:"line",section:"Links",value:"A finance resolver by construction"},"LEDGER.HREF":{label:"Finance resolver target",kind:"link",section:"Links",value:"route:stats/ledger"}}});
;
