ArkManifest.define({id:"download",title:"Get FXN Browser",route:"/download",group:"page",meta:{next:"deploy"},fields:{TITLE:{label:"Heading",kind:"line",section:"Page",value:"Get FXN Browser"},LEDE:{label:"Lede under the title",kind:"line",section:"Page",value:"The FXN Browser opens DEFXN sites and keeps your FXN ID on your own machine. It has no public download yet."},BACK:{label:"Link above the title, back to the products",kind:"line",section:"Page",value:"Back to products"},"NEXT.LINE":{label:"Next card, one line under its name",kind:"line",section:"Page",value:"Do this once your miner runs."},"APPS.NOTE":{label:"Line under Get the apps",kind:"line",section:"Page",value:"Each app gets its download here when it is published."},"ASIDE.LINE":{label:"Related link: Bundle Deployer, one line",kind:"line",section:"Page",value:"Put a DEFXN site on the network."},"GUIDE.LINE":{label:"Related link: operator guide, one line",kind:"line",section:"Page",value:"Every step in full, with the defaults."},"MOMENT1.TITLE":{label:"What it does, 1: name",kind:"line",section:"Page",value:"Opens DEFXN sites"},"MOMENT1.LINE":{label:"What it does, 1: one line",kind:"line",section:"Page",value:"Type a defxn:// address and the site opens in the browser."},"MOMENT2.TITLE":{label:"What it does, 2: name",kind:"line",section:"Page",value:"Holds your FXN ID"},"MOMENT2.LINE":{label:"What it does, 2: one line",kind:"line",section:"Page",value:"Sites ask the browser to sign. Your key stays on your machine."},"MOMENT3.TITLE":{label:"What it does, 3: name",kind:"line",section:"Page",value:"Reaches the network"},"MOMENT3.LINE":{label:"What it does, 3: one line",kind:"line",section:"Page",value:"It will connect to the DEFXN devnet once devnet starts. Nothing on it will be live money."},"MOMENTS.LABEL":{label:"What it does: the list name",kind:"line",section:"Page",value:"What the FXN Browser does"},DECK:{label:"Intro",kind:"text",section:"Page",value:"The first build is for macOS. Until it is published, you can do two things today. Initiate FXN ID on this site, or run a miner from source with the five steps in the terminal."},"POINT1.TITLE":{label:"Heading",kind:"line",section:"Point 1",value:"1. Check the runtime."},"POINT1.TEXT":{label:"Text",kind:"text",section:"Point 1",value:"Install Node.js 22 or newer with npm. The miner also needs a folder it can write to and a free status port."},"POINT2.TITLE":{label:"Heading",kind:"line",section:"Point 2",value:"2. Install the trusted checkout."},"POINT2.TEXT":{label:"Text",kind:"text",section:"Point 2",value:"In ark-miner-cli, install, copy .env.example to .env, review it, then start. The DEFXN miner is the flux-miner command."},"POINT3.TITLE":{label:"Heading",kind:"line",section:"Point 3",value:"3. Verify the process."},"POINT3.TEXT":{label:"Text",kind:"text",section:"Point 3",value:"The daemon should stay running and answer on its status listener. Note the source revision and package version. Keep a copy of the configuration you started with."},"POINT4.TITLE":{label:"Heading",kind:"line",section:"Point 4",value:"4. Know what success proves."},"POINT4.TEXT":{label:"Text",kind:"text",section:"Point 4",value:"A clean local start proves your miner starts. It does not mean any resolver is served, and says nothing about the public network or production."},"POINT5.TITLE":{label:"Heading",kind:"line",section:"Point 5",value:"5. Continue with a named network."},"POINT5.TEXT":{label:"Text",kind:"text",section:"Point 5",value:"With the miner and flux-network CLI installed, pick or create a network ID and start the miner against it."},NEXT:{label:"Onward link (an arrow is added)",kind:"line",section:"Links",value:"CREATE OR JOIN A NETWORK"},GUIDE:{label:"Operator documentation link",kind:"line",section:"Links",value:"Read the operator guide"},"GUIDE.HREF":{label:"Operator documentation target",kind:"link",section:"Links",value:"doc:docs/operators/run-from-source.md"},"ASIDE.HREF":{label:"Bundle Deployer aside link",kind:"link",section:"Links",value:"route:bundledeployer"},"APPS.TITLE":{label:"Apps: heading",kind:"line",section:"Apps",value:"Get the apps"},"APP.CLI.NAME":{label:"flux-miner (command line): name",kind:"line",section:"Apps",value:"flux-miner (command line)"},"APP.CLI.PLATFORMS":{label:"flux-miner (command line): systems",kind:"line",section:"Apps",value:"Terminal"},"APP.CLI.TEXT":{label:"flux-miner (command line): what it is",kind:"text",section:"Apps",value:"A miner without a window. It runs your machine\u2019s share of the network from a terminal. Not public yet: run it from source below."},"APP.CLI.URL":{label:"flux-miner (command line): download address (https://..., empty until published)",kind:"line",section:"Apps",value:""},"APP.DESKTOP.NAME":{label:"Flux Miner Desktop: name",kind:"line",section:"Apps",value:"Flux Miner Desktop"},"APP.DESKTOP.PLATFORMS":{label:"Flux Miner Desktop: systems",kind:"line",section:"Apps",value:"Desktop"},"APP.DESKTOP.TEXT":{label:"Flux Miner Desktop: what it is",kind:"text",section:"Apps",value:"The same miner with a desktop window. Not public yet."},"APP.DESKTOP.URL":{label:"Flux Miner Desktop: download address (https://..., empty until published)",kind:"line",section:"Apps",value:""},"APP.BROWSER.NAME":{label:"FXN Browser: name",kind:"line",section:"Apps",value:"FXN Browser"},"APP.BROWSER.PLATFORMS":{label:"FXN Browser: systems",kind:"line",section:"Apps",value:"macOS"},"APP.BROWSER.TEXT":{label:"FXN Browser: what it is",kind:"text",section:"Apps",value:"Opens DEFXN sites and holds your FXN ID. Windows and Linux builds are not made yet."},"APP.BROWSER.URL":{label:"FXN Browser: download address (https://..., empty until published)",kind:"line",section:"Apps",value:""},"APP.MOBILE.NAME":{label:"FXN Browser for phones: name",kind:"line",section:"Apps",value:"FXN Browser for phones"},"APP.MOBILE.PLATFORMS":{label:"FXN Browser for phones: systems",kind:"line",section:"Apps",value:"iOS \xB7 Android"},"APP.MOBILE.TEXT":{label:"FXN Browser for phones: what it is",kind:"text",section:"Apps",value:"Opens DEFXN sites and runs a node on your phone. It is in no store yet."},"APP.MOBILE.URL":{label:"FXN Browser for phones: download address (https://..., empty until published)",kind:"line",section:"Apps",value:""}}});
;
/* ---- js/content/manifests/bundledeployer.js ---- */
ArkManifest.define({id:"bundledeployer",title:"FXN Bundle Deployer",route:"/bundle-deployer",group:"page",meta:{back:"account"},fields:{EYEBROW:{label:"Eyebrow",kind:"line",section:"Page",value:"DEPLOYMENT / LOCAL CLI"},TITLE:{label:"Heading",kind:"line",section:"Page",value:"FXN Bundle Deployer"},DECK:{label:"Intro",kind:"text",section:"Page",value:"What it is: a command-line tool that publishes a site bundle from your own machine. What you do: prepare the bundle, review what becomes public, sign it with your FXN ID. What you get back: a signed ownership record for your site. Status: the CLI is not released. The bundle upload door is live on the old infra."},"POINT1.TITLE":{label:"Heading",kind:"line",section:"Point 1",value:"Prepare locally."},"POINT1.TEXT":{label:"Text",kind:"text",section:"Point 1",value:"Run the FXN Bundle Deployer on your machine when it is released. Your project and editing tools stay local."},"POINT2.TITLE":{label:"Heading",kind:"line",section:"Point 2",value:"Review what becomes public."},"POINT2.TEXT":{label:"Text",kind:"text",section:"Point 2",value:"Review the content and assets you intend to share before you send your bundle out."},"POINT3.TITLE":{label:"Heading",kind:"line",section:"Point 3",value:"Publish with your identity."},"POINT3.TEXT":{label:"Text",kind:"text",section:"Point 3",value:"Sign the site\u2019s mesh ownership record. The current verified mesh owner becomes the site maintainer and controls deployed CMS access. A bridge also writes bundle records to the bundle resolver chain; the mesh path above is still the one in use."},"POINT4.TITLE":{label:"Heading",kind:"line",section:"Point 4",value:"The CLI is in development."},"POINT4.TEXT":{label:"Text",kind:"text",section:"Point 4",value:"The lightweight FXN Bundle Deployer is not available yet. Installation instructions and supported commands will appear here when it is released."},BACK:{label:"Back link",kind:"line",section:"Links",value:"Back to your account"},HANDOFF:{label:"Bundles hand-off",kind:"text",section:"Links",value:"In the Bundles app you approve a site bundle on your own machine, pin it, and point your name at it."},STATUS:{label:"Status",kind:"text",section:"Deployer layout",value:"CLI in development"},"FLOW.TITLE":{label:"Flow / Title",kind:"text",section:"Deployer layout",value:"How a bundle travels"},"FLOW.LOCAL":{label:"Flow / Local",kind:"text",section:"Deployer layout",value:"Your project"},"FLOW.BUNDLE":{label:"Flow / Bundle",kind:"text",section:"Deployer layout",value:"Reviewed bundle"},"FLOW.MESH":{label:"Flow / Mesh",kind:"text",section:"Deployer layout",value:"Public network"},"FLOW.NOTE":{label:"Flow / Note",kind:"text",section:"Deployer layout",value:"Planned workflow / CLI not released"},"WORKFLOW.TITLE":{label:"Workflow / Title",kind:"text",section:"Deployer layout",value:"Steps"},"BOUNDARY.TITLE":{label:"Boundary / Title",kind:"text",section:"Deployer layout",value:"What becomes public"},"BOUNDARY.PUBLIC":{label:"Boundary / Public",kind:"text",section:"Deployer layout",value:"Becomes public"},"BOUNDARY.LOCAL":{label:"Boundary / Local",kind:"text",section:"Deployer layout",value:"Stays on your machine"},PUBLIC1:{label:"Public1",kind:"text",section:"Deployer layout",value:"Site content and selected assets"},PUBLIC2:{label:"Public2",kind:"text",section:"Deployer layout",value:"Signed mesh ownership record"},PUBLIC3:{label:"Public3",kind:"text",section:"Deployer layout",value:"Public maintainer identity"},LOCAL1:{label:"Local1",kind:"text",section:"Deployer layout",value:"FXN ID file and private signing keys"},LOCAL2:{label:"Local2",kind:"text",section:"Deployer layout",value:"Recovery phrase, PIN and password"},LOCAL3:{label:"Local3",kind:"text",section:"Deployer layout",value:"API credentials and local configuration"},"BOUNDARY.NOTE":{label:"Boundary / Note",kind:"text",section:"Deployer layout",value:"Review this boundary before you publish. Anyone can read a public bundle."},"RELEASE.NOTE":{label:"Release / Note",kind:"text",section:"Deployer layout",value:"Browsing this site or signing in does not deploy a bundle. Planned: sites and apps will deploy from deploy.defxn.com as signed records on the bundle resolver chain. Not built yet."}}});
;
/* ---- js/content/manifests/deploy.js ---- */
ArkManifest.define({id:"deploy",title:"Create or join a network",route:"/deploy",group:"page",meta:{back:"download"},fields:{EYEBROW:{label:"Eyebrow",kind:"line",section:"Page",value:"OPERATE DEFXN / NAMED NETWORKS"},TITLE:{label:"Heading",kind:"line",section:"Page",value:"Choose a network for miner presence."},DECK:{label:"Intro",kind:"text",section:"Page",value:"A named network decides which group of miners your machine shows up in. Accounts, identities, DAOs, records and treasuries are shared by every network, so a network is not a security boundary."},"RESOLVER.NOTE":{label:"Resolver deployment pointer",kind:"text",section:"Page",value:"This page joins your machine to a named network. Deploying a resolver happens in the Deploy product, and the resolver gets its own chain."},"RESOLVER.LINK":{label:"Resolver deployment link",kind:"line",section:"Page",value:"Resolve your deployments"},"RESOLVER.HREF":{label:"Resolver deployment link target",kind:"link",section:"Page",value:"route:resolutions/deployments"},BACK:{label:"Link back (an arrow is added)",kind:"line",section:"Links",value:"RUN DEFXN FROM SOURCE"},"BUNDLEDEPLOYER.HREF":{label:"Bundle Deployer link",kind:"link",section:"Links",value:"route:bundledeployer"},"GUIDE.HREF":{label:"Network scope guide link",kind:"link",section:"Links",value:"doc:docs/operators/networks.md"}}});
;
/* ---- js/content/manifests/dao.js ---- */
ArkManifest.define({id:"dao",title:"How DEFXN is governed",route:"/dao",group:"page",meta:{back:"concept",topic:"Governance",docs:"docs/protocol/governance.md",diagrams:[{id:"upgrade-supersedes",place:"dao: beside POINT6 (Who can change a resolver?)",caption:"Illustration \xB7 relationships, not live state",line:"a declaration head moves right; the old declaration stays on the line, greyed but present",declarations:["launch","upgrade","upgrade"],head:"current",superseded:"superseded, still on the line",variants:[{control:"key",mark:"key",label:"A control key was named at launch: each upgrade adds a declaration beside the old one",shows:3},{control:"immutable",mark:"lock",label:"Launched immutable: no upgrade can be signed, ever",shows:1}]}]},fields:{TITLE:{label:"Heading",kind:"line",section:"Page",value:"Who can change what?"},DECK:{label:"Intro",kind:"text",section:"Page",value:"What it is: the rules for who can change what. What you do: sign a proposal with your FXN ID if you are on a roster. What you get back: a signed decision record. On the devnet, a multisig of five FXN IDs changes fees, budget and parameters when 4 of 5 sign, until attesters are filed. Each launched chain gets its own DAO. Status: built, not live."},"POINT1.TITLE":{label:"Heading",kind:"line",section:"Point 1",value:"Mesh operations / scope"},"POINT1.TEXT":{label:"Text",kind:"text",section:"Point 1",value:"An earlier base policy in source names seven operators. Four must sign for ordinary admission, five for economic or runtime changes, three to pause and five to unpause. It governs the shared base, not a network\u2019s decisions, and it is not how a resolver changes."},"POINT2.TITLE":{label:"Heading",kind:"line",section:"Point 2",value:"Network DAO / scope"},"POINT2.TEXT":{label:"Text",kind:"text",section:"Point 2",value:"Each network defines its own roster, threshold, governed objects and activation rules. On the development network the DAO runs as its own resolver chain, built on the shared N-of-M signature capability: at least two signers, and a threshold of at least two. No public live example with complete evidence is established, so named deployments remain unverified."},"POINT3.TITLE":{label:"Heading",kind:"line",section:"Point 3",value:"Explicit non-authority"},"POINT3.TEXT":{label:"Text",kind:"text",section:"Point 3",value:`Mesh operations cannot decide a network's internal proposal. A network DAO cannot change the shared base. The word "governance" alone does not say who holds authority.`},"POINT4.TITLE":{label:"Heading",kind:"line",section:"Point 4",value:"Approval and activation are separate."},"POINT4.TEXT":{label:"Text",kind:"text",section:"Point 4",value:"A signed decision records consent under a policy. The change becomes active only after its separate activation conditions and evidence are satisfied."},"POINT5.TITLE":{label:"Heading",kind:"line",section:"Point 5",value:"Every claim needs a complete record."},"POINT5.TEXT":{label:"Text",kind:"text",section:"Point 5",value:"A governance record should identify the proposal, policy revision, roster, required threshold, approvals, activation condition, activation evidence, and observation time."},"POINT6.TITLE":{label:"Point 6 title",kind:"line",section:"Point 6",value:"Who can change a resolver?"},"POINT6.TEXT":{label:"Point 6 text",kind:"text",section:"Point 6",value:"The key its creator named at launch, or nobody. A resolver launched immutable can never change. An upgrade is a new signed declaration that sits beside the old one. Records signed under the old rules stay valid."},"POINT7.TITLE":{label:"Point 7 title",kind:"line",section:"Point 7",value:"Who can change a capability?"},"POINT7.TEXT":{label:"Point 7 text",kind:"text",section:"Point 7",value:"The same rule: the control key named when the capability was launched, or nobody. A capability controlled by a DAO is refused for now."},"STATUS.TITLE":{label:"Status heading",kind:"line",section:"Evidence",value:"Status / Partial"},"STATUS.TEXT":{label:"Status text",kind:"text",section:"Evidence",value:"The base policy and threshold rules exist in source, and the DAO runs as a resolver chain on the development network. A public governance page and a production activation do not exist yet."},"LIMIT.TITLE":{label:"Limitation heading",kind:"line",section:"Evidence",value:"Current evidence boundary"},"LIMIT.TEXT":{label:"Limitation text",kind:"text",section:"Evidence",value:"Policy text is not activation evidence. Each named network DAO needs its own roster record, decision records and activation records that anyone can inspect."},EVIDENCE:{label:"Canonical evidence link",kind:"line",section:"Links",value:"READ THE GOVERNANCE GUIDE"},BACK:{label:"Link back to the theory (an arrow is added)",kind:"line",section:"Links",value:"OPERATING MODEL"}}});
